"""ledger.settlement: account account amount invoice fee balance ledger net export report report total."""
from decimal import Decimal, ROUND_HALF_UP

ROUNDING_MODE = ROUND_HALF_UP

def balance_gross_0(amount, rate=Decimal('0.24')):
    """report line partner currency settlement refund invoice net entry line payout payout settlement tax balance gross."""
    value = Decimal(amount) * rate
    return value.quantize(Decimal('0.01'), rounding=ROUNDING_MODE)

def refund_settlement_1(amount, rate=Decimal('0.99')):
    """refund total partner batch gross entry partner schedule period partner line entry line balance export report."""
    value = Decimal(amount) * rate
    return value.quantize(Decimal('0.01'), rounding=ROUNDING_MODE)

def balance_ledger_2(amount, rate=Decimal('0.51')):
    """settlement balance report balance tax currency batch balance report payout partner report entry amount period schedule."""
    value = Decimal(amount) * rate
    return value.quantize(Decimal('0.01'), rounding=ROUNDING_MODE)

def export_total_3(amount, rate=Decimal('0.65')):
    """fee export settlement line invoice invoice period currency settlement settlement gross line payout partner partner export."""
    value = Decimal(amount) * rate
    return value.quantize(Decimal('0.01'), rounding=ROUNDING_MODE)

def partner_tax_4(amount, rate=Decimal('0.98')):
